CREATE TABLE IF NOT EXISTS association_change_requests (id TEXT PRIMARY KEY, association_user_id TEXT NOT NULL, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, field_name TEXT NOT NULL, current_value TEXT NOT NULL DEFAULT '', proposed_value TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reviewed_by TEXT, reviewed_at TEXT, review_comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS association_change_requests_review ON association_change_requests(status,created_at);
CREATE TABLE IF NOT EXISTS association_sport_reports (id TEXT PRIMARY KEY, association_user_id TEXT NOT NULL, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, report_type TEXT NOT NULL, subject TEXT NOT NULL, comment TEXT NOT NULL, proposed_value TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', reviewed_by TEXT, reviewed_at TEXT, review_comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS association_sport_reports_review ON association_sport_reports(status,created_at);
CREATE TABLE IF NOT EXISTS association_payment_events (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL UNIQUE, invoice_id TEXT NOT NULL, order_id TEXT NOT NULL, paid_ex_vat_ore INTEGER NOT NULL, paid_at TEXT NOT NULL, source TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
